checkpoint=R/'evidence/AGGREGATE_CHECKPOINT.json'
def test_hashes():
 paths=list((R/'tests').glob('*.gd'))+[Path(__file__)]
 return {str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(paths)}
def atomic_json(path,value):
 tmp=path.with_suffix(path.suffix+'.tmp');tmp.write_text(json.dumps(value,ensure_ascii=False,indent=2));tmp.replace(path)
started=time.time();before_hashes=source_hashes();before_tests=test_hashes();rows=[];elapsed_before=0;segments=1
if checkpoint.exists():
 saved=json.loads(checkpoint.read_text())
 if saved.get('status')=='RUNNING' and saved.get('source_sha256')==before_hashes and saved.get('test_sha256')==before_tests and [r['name'] for r in saved.get('tests',[])]==NAMES[:len(saved.get('tests',[]))]:
  rows=saved['tests'];elapsed_before=saved.get('elapsed_seconds',0);segments=saved.get('segments',1)+1
resumed=len(rows)
def persist(status='RUNNING'):
 atomic_json(checkpoint,{'status':status,'tests':rows,'source_sha256':before_hashes,'test_sha256':before_tests,'elapsed_seconds':elapsed_before+time.time()-started,'segments':segments})
persist();atomic_json(R/'evidence/AGGREGATE.json',{'passed':False,'status':'RUNNING','headless_only':True,'completed_suites':len(rows),'checkpoint':'AGGREGATE_CHECKPOINT.json'})
print('RESUME completed='+str(resumed)+' total='+str(len(NAMES)),flush=True)
for name in NAMES[resumed:]:
 print(name,'RUNNING',flush=True)
 try:
  p=subprocess.run(['godot','--headless','--path',str(R/'project'),'--script',str(R/'tests'/f'{name}.gd')],env=env,text=True,capture_output=True,timeout=300 if name.startswith(('chapter_five','chapter_six','chapter_seven','chapter_eight','chapter_nine','expedition','controller_chapter')) else (240 if name in ['native_later_save','controller_day_eleven'] else 120))
 except (OSError,subprocess.TimeoutExpired) as exc:
  stdout=getattr(exc,'stdout','') or '';stderr=getattr(exc,'stderr','') or ''
  if isinstance(stdout,bytes):stdout=stdout.decode('utf-8',errors='replace')
  if isinstance(stderr,bytes):stderr=stderr.decode('utf-8',errors='replace')
  (R/'evidence'/f'{name}.log').write_text(stdout+'\n'+stderr+'\n'+str(exc));rows.append({'name':name,'passed':False,'error':str(exc)});persist();continue
 output=p.stdout+'\n'+p.stderr;(R/'evidence'/f'{name}.log').write_text(output)
 js=[json.loads(line) for line in p.stdout.splitlines() if line.startswith('{')];errors=any(x in output for x in ['ERROR:','SCRIPT ERROR','SHADER ERROR'])
